#include <cassert>
#include <cstdio>
#include <iostream>
#include <sqlite3.h>
#include <openssl/sha.h>
#include "intent_processor.h"
#include "canonical_cbor.h"
using namespace beefiscal::idf;
namespace beefiscal::idf {esp_err_t canonical_cbor_to_json(const uint8_t*,size_t,cJSON**){return ESP_ERR_NOT_SUPPORTED;}}
static void sql(const char*path,const char*query){sqlite3*d{};assert(sqlite3_open(path,&d)==SQLITE_OK);char*err{};int rc=sqlite3_exec(d,query,nullptr,nullptr,&err);if(rc)std::cerr<<(err?err:"")<<"\n";assert(rc==SQLITE_OK);sqlite3_free(err);sqlite3_close(d);}
static std::string scalar(const char*path,const char*query){sqlite3*d{};sqlite3_stmt*s{};assert(sqlite3_open(path,&d)==0);assert(sqlite3_prepare_v2(d,query,-1,&s,nullptr)==0);assert(sqlite3_step(s)==SQLITE_ROW);auto*t=sqlite3_column_text(s,0);std::string r=t?(const char*)t:"";sqlite3_finalize(s);sqlite3_close(d);return r;}
static std::string digest(const std::string&s){unsigned char out[32];SHA256((const unsigned char*)s.data(),s.size(),out);char b[65];for(int n=0;n<32;n++)snprintf(b+n*2,3,"%02x",out[n]);return b;}
static std::string command(bool sale,bool cash=false){std::string payload=sale?R"({"items":[{"line_id":"00000000-0000-4000-8000-000000000003","name":"Item","quantity":"1","unit_price":{"amount":"2.00"},"tax_group":"A"}],"payments":[{"payment_id":"00000000-0000-4000-8000-000000000004","type":"CARD","amount":{"amount":"1.00","currency":"EUR"}},{"payment_id":"00000000-0000-4000-8000-000000000005","type":"CARD","amount":{"amount":"1.00","currency":"EUR"}}]})":"{}";
// Both payment IDs are UUIDs, intentionally distinct from operation/session IDs.

if(cash){size_t pos=0;while((pos=payload.find("CARD",pos))!=std::string::npos){payload.replace(pos,4,"CASH");pos+=4;}}
return "{\"intent_id\":\"00000000-0000-4000-8000-000000000001\",\"receipt_session_id\":\"00000000-0000-4000-8000-000000000002\",\"action\":\""+std::string(sale?"SALE_FINALIZE":"DEVICE_IDENTITY")+"\",\"tenant_id\":\"t\",\"register_id\":\"r\",\"edge_device_id\":\"e\",\"binding_generation\":1,\"payload_sha256\":\""+digest(payload)+"\",\"canonical_payload\":"+payload+"}";}
struct Executor:ReceiptExecutor{DurableStorage&s;int calls{};bool cards;Executor(DurableStorage&v,bool c):s(v),cards(c){}bool ready()override{return true;}ExecutionResult execute(const ReceiptPlan&p)override{++calls;if(cards)for(size_t n=0;n<p.payments.size();n++){auto&v=p.payments[n];assert(s.upsert_payment(v.id.c_str(),p.operation_id.c_str(),p.receipt_session_id.c_str(),"CARD_APPROVED",v.amount_minor,("terminal"+std::to_string(n)).c_str(),("rrn"+std::to_string(n)).c_str(),("auth"+std::to_string(n)).c_str(),1704067201)==ESP_OK);}return{ExecutionCertainty::Committed,"fiscal-1","","aggregate","aggregate-rrn","aggregate-auth"};}ExecutionResult recover(const RecoveryItem&)override{return{};}};
int main(int argc,char**argv){assert(argc==3);std::string mode=argv[1];const char*path=argv[2];remove(path);DurableStorage storage;assert(storage.open_database_for_test(path)==ESP_OK);assert(storage.configure_authority("TEST-",1,100,1)==ESP_OK);if(mode=="checkpoint")sql(path,"CREATE TRIGGER fault BEFORE UPDATE OF state ON operations WHEN NEW.state='EXECUTING' BEGIN SELECT RAISE(ABORT,'checkpoint fault'); END;");if(mode=="outbox")sql(path,"CREATE TRIGGER fault BEFORE INSERT ON event_outbox WHEN NEW.kind='RECEIPT_RESULT' BEGIN SELECT RAISE(ABORT,'outbox fault'); END;");if(mode=="payment")sql(path,"CREATE TRIGGER fault BEFORE UPDATE ON payments BEGIN SELECT RAISE(ABORT,'payment fault'); END;");if(mode=="collision")sql(path,"CREATE TRIGGER collide AFTER INSERT ON operations BEGIN INSERT INTO event_outbox(event_id,operation_id,kind,payload,payload_digest,created_at) VALUES('result-'||NEW.operation_id,NEW.operation_id,'RECEIPT_RESULT','{}','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',1704067201); END;");if(mode=="receipt")sql(path,"CREATE TRIGGER fault BEFORE UPDATE ON receipts BEGIN SELECT RAISE(ABORT,'receipt fault'); END;");bool cards=mode=="cards";Executor executor(storage,cards);CompositeBinding binding;binding.tenant_id="t";binding.register_id="r";binding.edge_device_id="e";binding.generation=1;IntentProcessor processor(storage,binding,executor,"");auto cmd=command(cards||mode=="payment",mode=="payment");auto result=processor.accept({(const uint8_t*)cmd.data(),cmd.size(),Ingress::Http});
if(mode=="checkpoint"){assert(result!=ESP_OK);assert(executor.calls==0);assert(scalar(path,"SELECT state FROM operations")=="RESERVED");}
else if(mode=="outbox"||mode=="receipt"||mode=="payment"||mode=="collision"){assert(result!=ESP_OK);assert(executor.calls==1);assert(scalar(path,"SELECT state FROM operations")=="EXECUTING");assert(scalar(path,"SELECT state FROM receipts")=="RESERVED");assert(scalar(path,"SELECT count(*) FROM event_outbox WHERE kind='RECEIPT_RESULT'")==(mode=="collision"?"1":"0"));}
else {assert(result==ESP_OK);assert(executor.calls==1);assert(scalar(path,"SELECT state FROM operations")=="COMMITTED");assert(scalar(path,"SELECT count(*) FROM event_outbox WHERE kind='RECEIPT_RESULT'")=="1");if(cards){assert(scalar(path,"SELECT count(DISTINCT rrn) FROM payments")=="2");assert(scalar(path,"SELECT count(*) FROM payments WHERE terminal_reference IN ('terminal0','terminal1')")=="2");}}
if(mode=="normal"||mode=="cards"){assert(processor.accept({(const uint8_t*)cmd.data(),cmd.size(),Ingress::Http})==ESP_OK);assert(executor.calls==1);}
storage.close();assert(storage.open_database_for_test(path)==ESP_OK);assert(!scalar(path,"SELECT state FROM operations").empty());std::cout<<mode<<" PASS (actual IntentProcessor + SQLite, reopened)\n";}
